SELECT d.* FROM edu_knowledge_doc d


        AND d.knowledge_doc_name LIKE CONCAT('%', #{query.knowledgeDocName}, '%')


        AND d.knowledge_doc_subject = #{query.knowledgeDocSubject}


        AND d.knowledge_doc_status = #{query.knowledgeDocStatus}



            AND (d.knowledge_doc_owner_user_id IS NULL OR d.knowledge_doc_owner_user_id = #{scope.ownerPredicate})



ORDER BY d.create_time DESC

SELECT d.* FROM edu_knowledge_doc d
d.knowledge_doc_status = 1
AND d.knowledge_doc_name LIKE CONCAT('%', #{keyword}, '%')
AND d.knowledge_doc_subject = #{subject}
AND (d.knowledge_doc_owner_user_id IS NULL OR d.knowledge_doc_owner_user_id = #{scope.ownerPredicate})
ORDER BY d.create_time DESC LIMIT #{limit}
